Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('ff59889beb92c5bada1cc24868a6eeb4f1f6578213cf3f80874f38ad24a4c049',), event=Revised(decision='compactasking', at=datetime(2026, 11, 24, 0, 0, 0), actor='assistant', title='Each summary records the version of how its class was asked; a stale summary is asked again and hidden meanwhile', body="Each summary records the version of how its node's class was asked (`compact_ask::Asking`, a `rule_version::Versioned` hashing what each class's log shows on a fixed probe, 2026-10-25), and one asked under an older version, or over a child's summary since replaced, is stale: asked again with the nodes the reader's view rests on first and then the rest, the owner's nodes first within each, lowest level first within that (`Compaction::owed`, `InView`), and while stale an owner's node's summary is shown to no reader (`suzatary secretary digest census` counts them). A summary of a span no longer in the tree is read as nothing and counted on a line of its own.", rationale='Decided 2026-10-25.', supersedes=()))